731→  function joinWaitlist(zip, email, name, wBtn) {
732→    // Store original button HTML so we can restore it exactly (same pattern as setBtnLoading)
733→    var wBtnOriginalHtml = wBtn.innerHTML;
734→
735→    wBtn.disabled = true;
736→    wBtn.classList.add('zcc-btn--loading');
737→    wBtn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
738→
739→    var payload = { shop: SHOP, zip: zip, email: email };
740→    if (name) payload.name = name;
741→
742→    function restoreBtn() {
743→      wBtn.disabled = false;
744→      wBtn.classList.remove('zcc-btn--loading');
745→      wBtn.innerHTML = wBtnOriginalHtml;
746→    }
747→
748→    fetch(API_BASE + "/api/waitlist", {
749→      method: "POST",
750→      headers: { "Content-Type": "application/json" },
751→      body: JSON.stringify(payload),
752→    })
753→      .then(function (r) { return r.json(); })
754→      .then(function (data) {
755→        var wlEl = wBtn.closest(".zcc-wl");
756→        if (data.success) {
757→          if (wlEl) wlEl.innerHTML =
758→            '<div class="zcc-wl-success">' +
759→            '<span class="zcc-wl-success-icon">' + ICONS.checkmark + '</span>' +
760→            '<span>Your request has been submitted! We\u2019ll notify you when delivery is available.</span>' +
761→            '</div>';
762→        } else {
763→          restoreBtn();
764→        }
765→      })
766→      .catch(function () {
767→        restoreBtn();
768→      });
769→  }
